import json
D=json.load(open('/workspace/contracts/openapi.contract.json'))

def shape(s):
 if '$ref' in s:return s['$ref'].split('/')[-1]
 if 'allOf' in s:return '&'.join(shape(x) for x in s['allOf'])
 t=s.get('type','?')
 if t=='array':return '['+shape(s.get('items',{}))+']'
 if t=='object':
  req=set(s.get('required',[])); return '{'+', '.join(k+('*' if k in req else '')+':'+shape(v) for k,v in s.get('properties',{}).items())+'}'
 return t+('('+('|'.join(map(str,s['enum'])))+')' if 'enum' in s else '')
for path,item in D['paths'].items():
 for m,op in item.items():
  if m not in ('get','post'):continue
  req=op.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema')
  success=next((r for c,r in op['responses'].items() if c.startswith('2')),None)
  out=(success or {}).get('content',{}).get('application/json',{}).get('schema',{})
  print(f"{op['operationId']}|{m.upper()} {path}|REQ {shape(req) if req else '-'}|OK {next(c for c in op['responses'] if c.startswith('2'))} {shape(out)}")
print('\nCOMPONENTS')
for n,s in D['components']['schemas'].items():print(n,'=',shape(s))
PY

