type App struct{ db *pgxpool.Pool; dist string }
type Actor struct{ ID uuid.UUID; Username, Role string; Roles []string }
type M = map[string]any
var roles = map[string]bool{"administrator":true,"dispatcher":true,"requester":true,"collection_professional":true,"delivery_partner":true,"node_handler":true,"laboratory_team":true}

func main(){
 ctx:=context.Background(); url:=os.Getenv("DATABASE_URL"); if url=="" { log.Fatal("DATABASE_URL is required") }
 db,err:=pgxpool.New(ctx,url); if err!=nil { log.Fatal(err) }; defer db.Close()
 db.Config().ConnConfig.RuntimeParams["search_path"]="labapp,public"
 if err=db.Ping(ctx); err!=nil { log.Fatal(err) }
 if err=ensureAdmin(ctx,db); err!=nil { log.Fatal(err) }
 a:=&App{db:db,dist:"/workspace/dist"}; mux:=http.NewServeMux(); mux.HandleFunc("/ready",a.ready); mux.HandleFunc("/api/",a.api); mux.HandleFunc("/",a.frontend)
 s:=&http.Server{Addr:"127.0.0.1:8080",Handler:securityHeaders(mux),ReadHeaderTimeout:10*time.Second}
 log.Printf("Relay listening on http://127.0.0.1:8080"); log.Fatal(s.ListenAndServe())
}
func ensureAdmin(ctx context.Context,db *pgxpool.Pool) error { var n int; if err:=db.QueryRow(ctx,"select count(*) from labapp.users").Scan(&n); err!=nil{return fmt.Errorf("database not reset: %w",err)}; if n>0{return nil}; u,p:=os.Getenv("ADMIN_USERNAME"),os.Getenv("ADMIN_PASSWORD"); if u==""||p==""{return errors.New("ADMIN_USERNAME and ADMIN_PASSWORD are required for first start")}; h,_:=bcrypt.GenerateFromPassword([]byte(p),bcrypt.DefaultCost); _,err:=db.Exec(ctx,"insert into labapp.users(username,password_hash,full_name,roles) values($1,$2,$1,array['administrator'])",u,string(h)); return err }
func securityHeaders(next http.Handler) http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.Header().Set("X-Content-Type-Options","nosniff");w.Header().Set("X-Frame-Options","DENY");w.Header().Set("Referrer-Policy","same-origin");next.ServeHTTP(w,r)})}
func (a *App) ready(w http.ResponseWriter,r *http.Request){if r.Method!="GET"{fail(w,405,"method_not_allowed","method not allowed");return}; if a.db.Ping(r.Context())!=nil{write(w,503,M{"status":"starting"});return};write(w,200,M{"status":"ready"})}
