func write(w http.ResponseWriter,status int,v any){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);_ = json.NewEncoder(w).Encode(v)}
func ok(w http.ResponseWriter,status int,v any){write(w,status,M{"data":v})}
func fail(w http.ResponseWriter,status int,code,msg string){write(w,status,M{"error":msg,"code":code})}
func decode(r *http.Request,v any) error{d:=json.NewDecoder(http.MaxBytesReader(nil,r.Body,1<<20));d.DisallowUnknownFields();return d.Decode(v)}
func uid() string{return uuid.NewString()}
func hashBody(v any)string{b,_:=json.Marshal(v);h:=sha256.Sum256(b);return hex.EncodeToString(h[:])}
func contains(a []string,s string)bool{for _,v:=range a{if v==s{return true}};return false}
func str(v any)string{if v==nil{return ""};return fmt.Sprint(v)}
func arr(v any)[]any{if x,ok:=v.([]any);ok{return x};return []any{}}
func num(v any)float64{if x,ok:=v.(float64);ok{return x};return 0}
