func hav(lat1,lon1,lat2,lon2 float64)float64{const R=6371.;dlat:=(lat2-lat1)*math.Pi/180;dlon:=(lon2-lon1)*math.Pi/180;s:=math.Sin(dlat/2)*math.Sin(dlat/2)+math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*math.Sin(dlon/2)*math.Sin(dlon/2);return 2*R*math.Asin(math.Sqrt(s))}
