nments,aid);_,e=tx.Exec(r.Context(),`insert into labapp.assignments(id,journey_id,sample_id,kind,sequence,to_location_id,worker_id,offered_to,status,offer_expires_at) values($1,$2,$3,'collection',0,$4,nullif($5,'')::uuid,nullif($5,'')::uuid,case when $5='' then 'pending' else 'offered' end,now()+interval '15 minutes')`,aid,jid,sid,s.OriginNode,worker)};aid:=uid();worker:=a.eligibleWorker(r.Context(),"delivery_partner","","");assignments=append(assignments,aid);_,e=tx.Exec(r.Context(),`insert into labapp.assignments(id,journey_id,sample_id,kind,sequence,from_location_id,to_location_id,worker_id,offered_to,status,offer_expires_at) values($1,$2,$3,'transport',1,$4,$5,nullif($6,'')::uuid,nullif($6,'')::uuid,case when $6='' then 'pending' else 'offered' end,now()+interval '15 minutes')`,aid,jid,sid,s.OriginNode,s.Lab,worker);cool:=s.Cooled;col:="reserved_units";if cool{col="cooled_reserved_units"};for _,res:=range []string{s.Connection,s.Lab}{tag,er:=tx.Exec(r.Context(),fmt.Sprintf("update labapp.capacities set %s=%s+1 where resource_id=$1 and %s+1<=case when $2 then cooled_capacity_units else capacity_units end",col,col,col),res,cool);if er!=nil||tag.RowsAffected()==0{e=errors.New("capacity")};_,_=tx.Exec(r.Context(),"insert into labapp.capacity_reservations(journey_id,resource_id,cooled,units) values($1,$2,$3,1)",jid,res,cool)}};if e!=nil{fail(w,409,"capacity_exhausted","capacity changed during planning");return};if e=tx.Commit(r.Context());e!=nil{fail(w,409,"concurrent_conflict","request conflicted");return};resp:=M{"requestId":rid,"sampleId":sid,"serviceability":map[bool]string{true:"serviceable",false:"unserviceable"}[s.Serviceable],"serviceabilityReason":s.Reason,"activeAssignmentIds":assignments,"earliestCollectionAt":earliest,"latestCollectionAt":latest,"alreadySealed":pre,"originType":originType};if jid!=""{resp["journeyId"]=jid;resp["targetLaboratoryId"]=s.Lab};a.audit(r.Context(),x,"create_collection_request","sample",sid,true,M{"requestId":rid});envelope:=M{"