func (a *App) lifecycle(w http.ResponseWriter,r *http.Request){x,yes:=a.require(w,r,"administrator","dispatcher","requester","collection_professional","delivery_partner","node_handler","laboratory_team");if !yes{return};var q M;if decode(r,&q)!=nil{fail(w,400,"invalid_json","invalid request");return};id:=str(q["sampleId"]);var status string;var sealed bool;var jid,holder,lab *uuid.UUID;var ex []byte;var loc []byte;var locAt *time.Time;if a.db.QueryRow(r.Context(),"select status,sealed_at is not null,active_journey_id,current_holder_id,target_laboratory_id,exception,latest_location,location_recorded_at from labapp.samples where id=$1",id).Scan(&status,&sealed,&jid,&holder,&lab,&ex,&loc,&locAt)!=nil{fail(w,404,"not_found","sample not found");return};if x.Role=="requester"{var owner string;_=a.db.QueryRow(r.Context(),"select r.requester_id from labapp.samples s join labapp.requests r on r.id=s.request_id where s.id=$1",id).Scan(&owner);if owner!=x.ID.String(){fail(w,403,"forbidden","not permitted");return}};m:=M{"sampleId":id,"status":status,"sealed":sealed,"completedLegIds":[]string{},"activeReplacementPlanIds":[]string{},"timeline":timeline(r.Context(),a.db,"sample",id),"locationStale":locAt==nil||time.Since(*locAt)>15*time.Minute};if jid!=nil{m["activeJourneyId"]=jid};if holder!=nil{m["currentHolderId"]=holder};if lab!=nil&&status=="received"{m["receivedLaboratoryId"]=lab};if len(ex)>0{m["exception"]=jsonMap(ex)};if locAt!=nil{m["latestLocation"]=jsonMap(loc);m["locationRecordedAt"]=locAt};ok(w,200,m)}

func (a *App) roleWork(w http.ResponseWriter,r *http.Request){x,e:=a.actor(r);if e!=nil{fail(w,401,"unauthorized","authentication required");return};var q M;if decode(r,&q)!=nil{fail(w,400,"invalid_json","invalid request");return};role:=str(q["role"]);if role==""{role=x.Role};if role!=x.Role{fail(w,403,"forbidden","work role must match active role");return};pending,inprog,done:=[]M{},[]M{},[]M{};if role=="requester"{for _,s:=range a.requesterSamples(r.Context(),x.ID){item:=M{"kind":"sample","sampleId":s["sampleId"],"requestId":s["requestId"],"status":s["status"],"history":timeline(r.Context(),a.db,"sample",str(s["sampleId"]))};if str(s["status"])=="received"||str(s["status"])=="cancelled"{done=append(done,item)}else{inprog=append(inprog,item)}}}else if roleAllowed(role,"administrator","dispatcher"){rows,_:=a.db.Query(r.Context(),"select id,status,route_mode,plan_version,sample_ids,coalesce(estimated_delivery_at,now()) from labapp.journeys order by created_at desc");defer rows.Close();for rows.Next(){var id,status,mode string;var version int;var samples []uuid.UUID;var eta time.Time;_=rows.Scan(&id,&status,&mode,&version,&samples,&eta);item:=M{"kind":"journey","journeyId":id,"status":status,"routeMode":mode,"planVersion":version,"sampleIds":samples,"estimatedDeliveryAt":eta,"assignmentCount":0,"history":timeline(r.Context(),a.db,"journey",id)};if status=="completed"||status=="cancelled"{done=append(done,item)}else{inprog=append(inprog,item)}}}else{rows,_:=a.db.Query(r.Context(),"select id,sample_id,kind,status,journey_id,from_location_id,to_location_id,sequence,offer_expires_at from labapp.assignments where worker_id=$1 or offered_to=$1 order by created_at desc",x.ID);defer rows.Close();for rows.Next(){var id,sid,kind,status,jid string;var from,to *uuid.UUID;var seq int;var exp *time.Time;_=rows.Scan(&id,&sid,&kind,&status,&jid,&from,&to,&seq,&exp);item:=M{"kind":kind,"assignmentId":id,"sampleId":sid,"status":status,"journeyId":jid,"sequence":seq,"history":timeline(r.Context(),a.db,"assignment",id)};if from!=nil{item["fromLocationId"]=from};if to!=nil{item["toLocationId"]=to};if exp!=nil{item["offerExpiresAt"]=exp};switch status{case "offered","pending":pending=append(pending,item);case "completed","declined","cancelled":done=append(done,item);default:inprog=append(inprog,item)}}};ok(w,200,M{"pending":pending,"inProgress":inprog,"completed":done})}

func (a *App) journeyData(ctx context.Context,id string,actor Actor)(M,error){var parent *uuid.UUID;var ver int;var mode,status string;var eta *time.Time;var cost float64;var used int;var samples []uuid.UUID;var stops []byte;var valid bool;var replan *string;if a.db.QueryRow(ctx,"select parent_journey_id,plan_version,route_mode,status,estimated_delivery_at,total_cost_units,capacity_used,sample_ids,ordered_stops,valid,replan_status from labapp.journeys where id=$1",id).Scan(&parent,&ver,&mode,&status,&eta,&cost,&used,&samples,&stops,&valid,&replan)!=nil{return nil,pgx.ErrNoRows};var os any;_=json.Unmarshal(stops,&os);legs:=[]M{};rows,_:=a.db.Query(ctx,"select id,sequence,status,from_location_id,to_location_id,worker_id,sample_id,kind from labapp.assignments where journey_id=$1 order by sequence",id);defer rows.Close();assigned:=[]uuid.UUID{};for rows.Next(){var aid,sid,st,kind string;var seq int;var from,to,worker *uuid.UUID;_=rows.Scan(&aid,&seq,&st,&from,&to,&worker,&sid,&kind);if actor.Role!="administrator"&&actor.Role!="dispatcher"&&actor.Role!="requester"&&worker!=nil&&*worker!=actor.ID{continue};l:=M{"assignmentId":aid,"sequence":seq,"status":st,"sampleId":sid};if from!=nil{l["fromLocationId"]=from};if to!=nil{l["toLocationId"]=to};if worker!=nil{l["workerId"]=worker;assigned=append(assigned,*worker)};legs=append(legs,l)};m:=M{"journeyId":id,"planVersion":ver,"routeMode":mode,"status":status,"sampleIds":samples,"orderedStops":os,"legs":legs};if actor.Role=="administrator"||actor.Role=="dispatcher"{m["totalCostUnits"]=cost;m["capacityUsed"]=used;m["capacityAvailable"]=used;m["assignedWorkerIds"]=assigned;m["valid"]=valid};if actor.Role!="requester"&&actor.Role!="administrator"&&actor.Role!="dispatcher"{m["scope"]="assigned_legs";ids:=[]string{};for _,l:=range legs{ids=append(ids,str(l["assignmentId"]))};m["assignmentIds"]=ids};if parent!=nil{m["parentJourneyId"]=parent};if eta!=nil{m["estimatedDeliveryAt"]=eta};if replan!=nil{m["replanStatus"]=*replan};return m,nil}
func (a *App) readJourney(w http.ResponseWriter,r *http.Request){x,yes:=a.require(w,r,"administrator","dispatcher","requester","collection_professional","delivery_partner","node_handler","laboratory_team");if !yes{return};var q M;if decode(r,&q)!=nil{fail(w,400,"invalid_json","invalid request");return};m,e:=a.journeyData(r.Context(),str(q["journeyId"]),x);if e!=nil{fail(w,404,"not_found","journey not found");return};if x.Role=="requester"{var count int;_=a.db.QueryRow(r.Context(),"select count(*) from labapp.journeys j join labapp.samples s on s.id=any(j.sample_ids) join labapp.requests r on r.id=s.request_id where j.id=$1 and r.requester_id=$2",str(q["journeyId"]),x.ID).Scan(&count);if count==0{fail(w,403,"forbidden","not permitted");return}};ok(w,200,m)}

