var(--line);background:white;color:var(--ink);padding:9px 13px;border-radius:7px;font-weight:600}.page>main{padding:28px 32px;max-width:1600px;margin:auto}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin-bottom:18px}.metric{background:white;border:1px solid var(--line);border-radius:10px;padding:17px 19px;position:relative;overflow:hidden}.metric:before{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--green)}.metric.danger:before{background:var(--orange)}.metric p{font-size:9px;letter-spacing:1.2px;color:var(--muted);font-weight:700;margin:0}.metric strong{font:700 30px Manrope;display:block;margin:6px 0 3px}.metric span{font-size:11px;color:var(--muted)}.grid-main{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(280px,.75fr);gap:18px}.panel{background:white;border:1px solid var(--line);border-radius:10px;overflow:hidden}.panel-head{padding:18px 20px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.panel h2{font:700 18px Manrope;margin:4px 0}.map{height:430px}.live{font-size:10px;letter-spacing:1px;color:#348568;background:#e8f5ee;padding:6px 9px;border-radius:20px}.feed{padding:5px 18px}.feed-row{display:grid;grid-template-columns:36px 1fr auto;gap:10px;align-items:center;padding:14px 0;border-bottom:1px solid #edf0ed}.feed-row small,.capacity small{display:block;color:var(--muted);margin-top:4px}.feed-row time{font-size:9px;color:var(--muted)}.sample-icon{background:#e0efea;color:var(--green);width:30px;height:30px;border-radius:7px;display:grid;place-items:center}.sample-icon.bad{background:#fae9e1;color:var(--orange)}.muted{color:var(--muted)}.alert,.success{padding:12px 14px;border-radius:7px;margin:14px 20px;background:#fff0e8;color:#9d461f;border:1px solid #f0c7b3}.success{background:#e8f5ee;color:#176b62;border-color:#bddfd0}.success small{display:block;margin-top:4px}.primary{border:0;border-radius:7px;background:var(--green);color:white;padding