import React,{useEffect,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import maplibregl from 'maplibre-gl';
import {Protocol} from 'pmtiles';
import 'maplibre-gl/dist/maplibre-gl.css';
import './styles.css';

type Obj=Record<string,any>;
const API='/api';
function App(){
 const [token,setToken]=useState(localStorage.getItem('relayToken')||'');
 const [boot,setBoot]=useState<Obj|null>(null),[error,setError]=useState(''),[view,setView]=useState('overview');
 const call=async(path:string,body?:Obj)=>{const r=await fetch(API+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:body?JSON.stringify(body):undefined});const j=await r.json();if(!r.ok)throw new Error(j.error||j.code);return j.data};
 const refresh=async()=>{try{setBoot(await call('/ui/bootstrap'));setError('')}catch(e:any){setError(e.message);if(e.message.includes('authentication'))logout()}};
 useEffect(()=>{if(token)refresh()},[token]);
 const logout=()=>{localStorage.removeItem('relayToken');setToken('');setBoot(null)};
 if(!token)return <Login onLogin={(t)=>{localStorage.setItem('relayToken',t);setToken(t)}}/>;
 if(!boot)return <main className="center"><div className="brand-mark">R</div><p>{error||'Loading control tower…'}</p></main>;
 const user=boot.user, role=user.activeRole;
 const switchRole=async(e:React.ChangeEvent<HTMLSelectElement>)=>{await call('/select-active-role',{role:e.target.value});await refresh()};
 return <div className="shell">
  <aside><div className="brand"><span className="brand-mark">R</span><div><b>Relay</b><small>CLINICAL LOGISTICS</small></div></div>
   <nav aria-label="Main navigation">
    <button className={view==='overview'?'active':''} onClick={()=>setView('overview')}>◈ <span>Overview</span></button>
    <button className={view==='work'?'active':''} onClick={()=>setView('work')}>▦ <span>My work</span></button>
    <button className={view==='samples'?'active':''} onClick={()=>setView('samples')}>◉ <span>Samples</span></button>
    {role==='requester'&&<button className={view==='request'?'active':''} onClick={()=>setView('request')}>＋ <span>New request</span></button>}
    {(role==='administrator'||role==='dispatcher')&&<><button className={view==='network'?'active':''} onClick={()=>setView('network')}>⌁ <span>Network</span></button><button className={view==='audit'?'active':''} onClick={()=>setView('audit')}>⌕ <span>Audit trail</span></button></>}
   </nav>
   <div className="aside-foot"><span className="status-dot"/> Systems operational</div>
  </aside>
  <section className="page"><header><div><p className="eyebrow">CONTROL TOWER / {role?.replaceAll('_',' ')||'SELECT ROLE'}</p><h1>{title(view)}</h1></div><div className="user-actions"><label>Working as<select aria-label="Active role" value={role} onChange={switchRole}><option value="" disabled>Select role</option>{user.roles.map((r:string)=><option key={r}>{r}</option>)}</select></label><div className="avatar">{(user.fullName||user.username).slice(0,2).toUpperCase()}</div><button className="ghost" onClick={logout}>Sign out</button></div></header>
   {error&&<div className="alert" role="alert">{error}</div>}
   <main>
    {user.roleSelectionRequired?<RoleGate roles={user.roles} choose={async(role)=>{await call('/select-active-role',{role});refresh()}}/>:
    view==='overview'?<Overview boot={boot} call={call} role={role}/>:
    view==='work'?<Work call={call} role={role}/>:
    view==='samples'?<Samples boot={boot} call={call} role={role}/>:
    view==='request'?<RequestForm call={call}/>:
    view==='audit'?<Audit call={call}/>:
    view==='network'?<Network call={call}/>:<Overview boot={boot} call={call} role={role}/>}</main>
  </section>
 </div>
}
function title(v:string){return ({overview:'Operations overview',work:'My work queue',samples:'Sample tracking',request:'Create collection',audit:'Audit trail',network:'Network & capacity'} as Obj)[v]}
function Login({onLogin}:{onLogin:(t:string)=>void}){const [username,setU]=useState(''),[password,setP]=useState(''),[error,setE]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setE('');const r=await fetch(API+'/authenticate-user',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username,password})});const j=await r.json();if(!r.ok){setE(j.error);return}onLogin(j.data.sessionToken)};return <div className="login"><section><div className="brand light"><span className="brand-mark">R</span><div><b>Relay</b><small>CLINICAL LOGISTICS</small></div></div><div className="login-copy"><p className="eyebrow">CHAIN OF CUSTODY, CONNECTED</p><h1>Every sample.<br/>Every handoff.<br/><em>Accounted for.</em></h1><p>Coordinate clinical logistics with confidence—from collection to laboratory receipt.</p></div><div className="chain">COLLECT <i/> SEAL <i/> TRANSPORT <i/> RECEIVE</div></section><form onSubmit={submit}><div><p className="eyebrow">SECURE ACCESS</p><h2>Welcome back</h2><p>Sign in to your operations workspace.</p>{error&&<div className="alert" role="alert">{error}</div>}<label>Username<input aria-label="Username" autoFocus value={username} onChange={e=>setU(e.target.value)} required/></label><label>Password<input aria-label="Password" type="password" value={password} onChange={e=>setP(e.target.value)} required/></label><button className="primary" type="submit">Sign in securely →</button><small className="secure">● Protected clinical operations environment</small></div></form></div>}
function RoleGate({roles,choose}:{roles:string[],choose:(r:string)=>void}){return <div className="empty"><h2>Choose your role context</h2><p>Your permissions and work queue follow the role you select.</p><div className="role-grid">{roles.map(r=><button className="card" key={r} onClick={()=>choose(r)}><b>{r.replaceAll('_',' ')}</b><span>Open workspace →</span></button>)}</div></div>}
function Overview({boot,call,role}:{boot:Obj,call:Function,role:string}){const [ops,setOps]=useState<Obj>(boot.operations||{});useEffect(()=>{if(role==='administrator'||role==='dispatcher')call('/read-operations-state',{filters:{}}).then(setOps)},[]);const samples=ops.samples||boot.requesterSamples||[];return <><div className="metrics"><Metric label="ACTIVE SAMPLES" value={samples.filter((s:Obj)=>!['received','cancelled'].includes(s.status)).length} trend="Live network"/><Metric label="IN TRANSIT" value={samples.filter((s:Obj)=>s.status==='in_transit').length} trend="On route"/><Metric label="EXCEPTIONS" value={samples.filter((s:Obj)=>s.status==='exception').length} danger trend="Needs action"/><Metric label="NETWORK NODES" value={(ops.locations||[]).length} trend="Configured"/></div><div className="grid-main"><div className="panel map-panel"><div className="panel-head"><div><p className="eyebrow">LIVE NETWORK</p><h2>Movement & custody</h2></div><span className="live">● LIVE</span></div><Map operations={ops}/></div><div className="panel"><div className="panel-head"><div><p className="eyebrow">PRIORITY QUEUE</p><h2>Attention needed</h2></div></div><div className="feed">{samples.slice(0,6).map((s:Obj)=><div className="feed-row" key={s.sampleId}><span className={'sample-icon '+(s.status==='exception'?'bad':'')}>◆</span><div><b>{s.sampleId.slice(0,8).toUpperCase()}</b><small>{s.status.replaceAll('_',' ')}</small></div><time>{s.locationStale?'STALE':'CURRENT'}</time></div>)}{!samples.length&&<p className="muted">No active samples yet.</p>}</div></div></div></>}
function Metric({label,value,trend,danger}:{label:string,value:number,trend:string,danger?:boolean}){return <div className={'metric '+(danger?'danger':'')}><p>{label}</p><strong>{value}</strong><span>{trend}</span></div>}
function Map({operations}:{operations:Obj}){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{if(!ref.current)return;const protocol=new Protocol();maplibregl.addProtocol('pmtiles',protocol.tile);const map=new maplibregl.Map({container:ref.current,center:[77.59,12.97],zoom:9,style:{version:8,sources:{local:{type:'vector',url:'pmtiles://'+location.origin+'/maps/bangalore.pmtiles'}},layers:[{id:'bg',type:'background',paint:{'background-color':'#e7ece8'}},{id:'roads',type:'line',source:'local','source-layer':'transportation',paint:{'line-color':'#aebbb3','line-width':1}}]}});map.addControl(new maplibregl.NavigationControl(),'bottom-right');map.on('load',()=>{(operations.locations||[]).forEach((l:Obj)=>new maplibregl.Marker({color:l.functions?.laboratory?'#c66b32':'#176b62'}).setLngLat([l.coordinate.longitude,l.coordinate.latitude]).setPopup(new maplibregl.Popup().setText(l.name)).addTo(map));(operations.workers||[]).filter((w:Obj)=>w.latestLocation).forEach((w:Obj)=>new maplibregl.Marker({color:'#172d2b',scale:.7}).setLngLat([w.latestLocation.longitude,w.latestLocation.latitude]).addTo(map))});return()=>map.remove()},[operations]);return <div ref={ref} className="map" aria-label="Live logistics map using local tiles"/>}
function Work({call,role}:{call:Function,role:string}){const [work,setWork]=useState<Obj>({pending:[],inProgress:[],completed:[]}),[tab,setTab]=useState('pending'),[msg,setMsg]=useState('');const load=()=>call('/list-role-work',{role}).then(setWork);useEffect(load,[role]);const act=async(id:string,accept:boolean)=>{await call(accept?'/accept-assignment':'/decline-assignment',{assignmentId:id,...(!accept&&{reason:'Not available'}),idempotencyKey:crypto.randomUUID()});setMsg(accept?'Assignment accepted':'Assignment declined');load()};const list=work[tab]||[];return <div className="panel"><div className="tabs" role="tablist">{[['pending','Offered'],['inProgress','In progress'],['completed','Past work']].map(([k,l])=><button role="tab" aria-selected={tab===k} className={tab===k?'active':''} onClick={()=>setTab(k)}>{l}<span>{(work[k]||[]).length}</span></button>)}</div>{msg&&<div className="success">{msg}</div>}<div className="work-list">{list.map((x:Obj)=><article key={x.assignmentId||x.sampleId||x.journeyId}><div><span className="tag">{x.kind}</span><h3>{(x.assignmentId||x.sampleId||x.journeyId).slice(0,12)}</h3><p>{x.status?.replaceAll('_',' ')} {x.deliveryDeadline&&`· Due ${new Date(x.deliveryDeadline).toLocaleString()}`}</p></div>{tab==='pending'&&x.assignmentId&&<div><button className="ghost" onClick={()=>act(x.assignmentId,false)}>Decline</button><button className="primary small" onClick={()=>act(x.assignmentId,true)}>Accept work</button></div>}<Timeline entries={x.history||[]}/></article>)}{!list.length&&<div className="empty"><h3>Queue is clear</h3><p>No {tab.replace(/([A-Z])/g,' $1').toLowerCase()} work in this role.</p></div>}</div></div>}
function Samples({boot,call,role}:{boot:Obj,call:Function,role:string}){const initial=boot.requesterSamples||boot.operations?.samples||[];const [samples,setSamples]=useState(initial),[selected,setSelected]=useState<Obj|null>(null),[error,setError]=useState('');const open=async(id:string)=>{try{setSelected(await call('/read-sample-lifecycle',{sampleId:id}))}catch(e:any){setError(e.message)}};return <div className="split"><div className="panel"><div className="panel-head"><div><p className="eyebrow">TRACKING</p><h2>Samples</h2></div><input aria-label="Search samples" placeholder="Search ID…" onChange={e=>setSamples(initial.filter((s:Obj)=>s.sampleId.includes(e.target.value)))}/></div><table><thead><tr><th>Sample</th><th>Status</th><th>Custodian</th><th>Freshness</th></tr></thead><tbody>{samples.map((s:Obj)=><tr onClick={()=>open(s.sampleId)} key={s.sampleId}><td><b>{s.sampleId.slice(0,8)}</b></td><td><span className={'pill '+s.status}>{s.status}</span></td><td>{s.currentHolderId?.slice(0,8)||'—'}</td><td>{s.locationStale?<span className="stale">● Stale</span>:<span className="fresh">● Current</span>}</td></tr>)}</tbody></table>{error&&<div className="alert">{error}</div>}</div>{selected&&<div className="panel detail"><button className="close" onClick={()=>setSelected(null)}>×</button><p className="eyebrow">SAMPLE LIFECYCLE</p><h2>{selected.sampleId.slice(0,12)}</h2>{selected.exception&&<div className="alert"><b>Exception flagged</b><br/>{selected.exception.reason}</div>}<dl><dt>Current status</dt><dd>{selected.status}</dd><dt>Current custodian</dt><dd>{selected.currentHolderId||'Not assigned'}</dd><dt>Location freshness</dt><dd>{selected.locationStale?'Stale':'Current'}</dd></dl><h3>Status history</h3><Timeline entries={selected.timeline}/></div>}</div>}
function Timeline({entries}:{entries:Obj[]}){return <ol className="timeline" aria-label="Status timeline">{entries.map((e,i)=><li key={e.eventId||i}><i/><div><b>{e.action.replaceAll('_',' ')}</b><small>{new Date(e.occurredAt).toLocaleString()} · {e.role||'system'}</small></div></li>)}</ol>}
function RequestForm({call}:{call:Function}){const [f,setF]=useState({latitude:'12.9716',longitude:'77.5946',sampleTypeId:'',earliest:'',latest:'',deadline:''}),[check,setCheck]=useState<Obj|null>(null),[msg,setMsg]=useState(''),[error,setError]=useState('');const payload=()=>({origin:{latitude:+f.latitude,longitude:+f.longitude},originType:'home',sampleTypeId:f.sampleTypeId,requestedAt:new Date().toISOString(),earliestCollectionAt:new Date(f.earliest).toISOString(),latestCollectionAt:new Date(f.latest).toISOString(),deliveryDeadline:new Date(f.deadline).toISOString()});const dry=async()=>{try{setError('');setCheck(await call('/check-serviceability',payload()))}catch(e:any){setError(e.message)}};const submit=async(e:React.FormEvent)=>{e.preventDefault();try{const p={...payload(),containerType:'standard',temperatureMinC:2,temperatureMaxC:25,idempotencyKey:crypto.randomUUID()};const d=await call('/create-collection-request',p);setMsg(`Request ${d.requestId.slice(0,8)} created`)}catch(e:any){setError(e.message)}};return <form className="panel request-form" onSubmit={submit}><div className="panel-head"><div><p className="eyebrow">NEW SERVICE</p><h2>Collection details</h2></div><span className="step">01 / 01</span></div>{error&&<div className="alert" role="alert">{error}</div>}{msg&&<div className="success">{msg}</div>}<div className="form-grid"><label>Origin latitude<input aria-label="Origin latitude" value={f.latitude} onChange={e=>setF({...f,latitude:e.target.value})}/></label><label>Origin longitude<input aria-label="Origin longitude" value={f.longitude} onChange={e=>setF({...f,longitude:e.target.value})}/></label><label className="wide">Sample type ID<input aria-label="Sample type ID" required value={f.sampleTypeId} onChange={e=>setF({...f,sampleTypeId:e.target.value})} placeholder="UUID from your sample catalogue"/></label><label>Earliest collection<input aria-label="Earliest collection" type="datetime-local" required value={f.earliest} onChange={e=>setF({...f,earliest:e.target.value})}/></label><label>Latest collection<input aria-label="Latest collection" type="datetime-local" required value={f.latest} onChange={e=>setF({...f,latest:e.target.value})}/></label><label className="wide">Laboratory delivery deadline<input aria-label="Delivery deadline" type="datetime-local" required value={f.deadline} onChange={e=>setF({...f,deadline:e.target.value})}/></label></div><div className="form-actions"><button type="button" className="ghost" onClick={dry}>Check serviceability</button><button type="submit" className="primary" disabled={!check?.serviceable}>Create request →</button></div>{check&&<div className={check.serviceable?'success':'alert'}><b>{check.serviceable?'Serviceable':'Not serviceable'}</b> · {check.reason.replaceAll('_',' ')}<small>Dry run · no capacity reserved · version {check.serviceabilityVersion}</small></div>}</form>}
function Audit({call}:{call:Function}){const [q,setQ]=useState(''),[data,setData]=useState<Obj>({entries:[]});const search=()=>call('/search-audit-trail',{query:q,limit:100,offset:0,order:'newest_first'}).then(setData);useEffect(search,[]);return <div className="panel"><div className="panel-head"><div><p className="eyebrow">IMMUTABLE HISTORY</p><h2>Audit events</h2></div><div className="search"><input aria-label="Search audit trail" placeholder="Action, item or ID" value={q} onChange={e=>setQ(e.target.value)}/><button onClick={search}>Search</button></div></div><table><thead><tr><th>Time</th><th>Action</th><th>Role</th><th>Affected item</th><th>Outcome</th></tr></thead><tbody>{data.entries.map((e:Obj)=><tr key={e.auditId}><td>{new Date(e.occurredAt).toLocaleString()}</td><td><b>{e.action.replaceAll('_',' ')}</b></td><td>{e.role||'system'}</td><td>{e.entityType} · {e.entityId.slice(0,10)}</td><td>{e.success?<span className="fresh">Success</span>:<span className="stale">Failed</span>}</td></tr>)}</tbody></table></div>}
function Network({call}:{call:Function}){const [ops,setOps]=useState<Obj>({locations:[],connections:[]});useEffect(()=>{call('/read-operations-state',{filters:{}}).then(setOps)},[]);return <div className="grid-main"><div className="panel"><div className="panel-head"><div><p className="eyebrow">FACILITIES</p><h2>Locations & capacity</h2></div></div>{ops.locations.map((l:Obj)=><div className="capacity" key={l.id}><div><b>{l.name}</b><small>{Object.keys(l.functions).filter(k=>l.functions[k]).join(' · ')}</small></div><div><span>Regular {l.capacity.reservedUnits}/{l.capacity.capacityUnits}</span><progress value={l.capacity.reservedUnits} max={l.capacity.capacityUnits||1}/></div><div><span>Cooled {l.capacity.cooledReservedUnits}/{l.capacity.cooledCapacityUnits}</span><progress value={l.capacity.cooledReservedUnits} max={l.capacity.cooledCapacityUnits||1}/></div></div>)}</div><div className="panel map-panel"><div className="panel-head"><h2>Network map</h2></div><Map operations={ops}/></div></div>}
createRoot(document.getElementById('root')!).render(<App/>);

