func hav(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.
	dlat := (lat2 - lat1) * math.Pi / 180
	dlon := (lon2 - lon1) * math.Pi / 180
	s := math.Sin(dlat/2)*math.Sin(dlat/2) + math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*math.Sin(dlon/2)*math.Sin(dlon/2)
	return 2 * R * math.Asin(math.Sqrt(s))
}

type svc struct {
	Serviceable             bool
	Reason, Lab, OriginNode string
	Arrival                 time.Time
	Version                 int
	Connection              string
	Cooled                  bool
}

func (a *App) service(ctx context.Context, q M) svc {
	out := svc{Reason: "outside_service_coverage", Version: 1}
	_ = a.db.QueryRow(ctx, "select max(version) from labapp.serviceability_snapshots").Scan(&out.Version)
	c, _ := q["origin"].(map[string]any)
	lat, lon := num(c["latitude"]), num(c["longitude"])
	origin := str(q["originNodeId"])
	if origin == "" {
		rows, _ := a.db.Query(ctx, "select id,latitude,longitude,coverage_km from labapp.locations where active and coalesce((functions->>'collection_point')::boolean,false)")
		defer rows.Close()
		best := 99999.
		for rows.Next() {
			var id string
			var la, lo, cv float64
			_ = rows.Scan(&id, &la, &lo, &cv)
			d := hav(lat, lon, la, lo)
			if d <= cv && d < best {
				best = d
				origin = id
			}
		}
	}
	if origin == "" {
		return out
	}
	out.OriginNode = origin
	var cooled bool
	_ = a.db.QueryRow(ctx, "select requires_cooled_route from labapp.sample_types where id=$1 and active", str(q["sampleTypeId"])).Scan(&cooled)
	out.Cooled = cooled
	row := a.db.QueryRow(ctx, `select l.id,c.id,now()+(c.travel_minutes+l.handling_minutes)*interval '1 minute' from labapp.connections c join labapp.locations l on l.id=c.to_location_id join labapp.lab_acceptance la on la.laboratory_id=l.id and la.sample_type_id=$2 and la.accepts left join labapp.capacities cp on cp.resource_id=c.id left join labapp.capacities lp on lp.resource_id=l.id where c.from_location_id=$1 and c.active and l.active and coalesce((l.functions->>'laboratory')::boolean,false) and (not $3 or c.cooled) and (case when $3 then coalesce(cp.cooled_capacity_units-cp.cooled_reserved_units,0)>0 and coalesce(lp.cooled_capacity_units-lp.cooled_reserved_units,0)>0 else coalesce(cp.capacity_units-cp.reserved_units,0)>0 and coalesce(lp.capacity_units-lp.reserved_units,0)>0 end) order by c.travel_minutes limit 1`, origin, str(q["sampleTypeId"]), cooled)
	if row.Scan(&out.Lab, &out.Connection, &out.Arrival) != nil {
		out.Reason = "no_route"
		return out
	}
	deadline, e := parseTime(q["deliveryDeadline"])
	if e != nil || out.Arrival.After(deadline) {
		out.Reason = "deadline_unreachable"
		return out
	}
	out.Serviceable = true
	out.Reason = "serviceable"
	return out
}
