		fail(w, 400, "invalid_deadline", "invalid delivery deadline")
		return
	}
	s := a.service(r.Context(), q)
	m := M{"serviceable": s.Serviceable, "reason": s.Reason, "serviceabilityVersion": s.Version}
	if s.Serviceable {
		m["targetLaboratoryId"] = s.Lab
		m["estimatedArrivalAt"] = s.Arrival
	}
	ok(w, 200, m)
}
