func (a *App) lifecycle(w http.ResponseWriter, r *http.Request) {
	x, yes := a.require(w, r, "administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !yes {
		return
	}
	var q M
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	id := str(q["sampleId"])
	var status string
	var sealed bool
	var jid, holder, lab *uuid.UUID
	var ex []byte
	var loc []byte
	var locAt *time.Time
	if a.db.QueryRow(r.Context(), "select status,sealed_at is not null,active_journey_id,current_holder_id,target_laboratory_id,exception,latest_location,location_recorded_at from labapp.samples where id=$1", id).Scan(&status, &sealed, &jid, &holder, &lab, &ex, &loc, &locAt) != nil {
		fail(w, 404, "not_found", "sample not found")
		return
	}
	if x.Role == "requester" {
		var owner string
		_ = a.db.QueryRow(r.Context(), "select r.requester_id from labapp.samples s join labapp.requests r on r.id=s.request_id where s.id=$1", id).Scan(&owner)
		if owner != x.ID.String() {
			fail(w, 403, "forbidden", "not permitted")
			return
		}
	}
	m := M{"sampleId": id, "status": status, "sealed": sealed, "completedLegIds": []string{}, "activeReplacementPlanIds": []string{}, "timeline": timeline(r.Context(), a.db, "sample", id), "locationStale": locAt == nil || time.Since(*locAt) > 15*time.Minute}
	if jid != nil {
		m["activeJourneyId"] = jid
	}
	if holder != nil {
		m["currentHolderId"] = holder
	}
	if lab != nil && status == "received" {
		m["receivedLaboratoryId"] = lab
	}
	if len(ex) > 0 {
		m["exception"] = jsonMap(ex)
	}
	if locAt != nil {
		m["latestLocation"] = jsonMap(loc)
		m["locationRecordedAt"] = locAt
	}
	ok(w, 200, m)
}

func (a *App) roleWork(w http.ResponseWriter, r *http.Request) {
	x, e := a.actor(r)
	if e != nil {
		fail(w, 401, "unauthorized", "authentication required")
		return
	}
	var q M
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	role := str(q["role"])
	if role == "" {
		role = x.Role
	}
	if role != x.Role {
		fail(w, 403, "forbidden", "work role must match active role")
		return
	}
	pending, inprog, done := []M{}, []M{}, []M{}
	if role == "requester" {
		for _, s := range a.requesterSamples(r.Context(), x.ID) {
			item := M{"kind": "sample", "sampleId": s["sampleId"], "requestId": s["requestId"], "status": s["status"], "history": timeline(r.Context(), a.db, "sample", str(s["sampleId"]))}
			if str(s["status"]) == "received" || str(s["status"]) == "cancelled" {
				done = append(done, item)
			} else {
				inprog = append(inprog, item)
			}
		}
	} else if roleAllowed(role, "administrator", "dispatcher") {
		rows, _ := a.db.Query(r.Context(), "select id,status,route_mode,plan_version,sample_ids,coalesce(estimated_delivery_at,now()) from labapp.journeys order by created_at desc")
		defer rows.Close()
		for rows.Next() {
			var id, status, mode string
			var version int
			var samples []uuid.UUID
			var eta time.Time
			_ = rows.Scan(&id, &status, &mode, &version, &samples, &eta)
			item := M{"kind": "journey", "journeyId": id, "status": status, "routeMode": mode, "planVersion": version, "sampleIds": samples, "estimatedDeliveryAt": eta, "assignmentCount": 0, "history": timeline(r.Context(), a.db, "journey", id)}
			if status == "completed" || status == "cancelled" {
				done = append(done, item)
			} else {
				inprog = append(inprog, item)
			}
		}
	} else {
		rows, _ := a.db.Query(r.Context(), "select id,sample_id,kind,status,journey_id,from_location_id,to_location_id,sequence,offer_expires_at from labapp.assignments where worker_id=$1 or offered_to=$1 order by created_at desc", x.ID)
		defer rows.Close()
		for rows.Next() {
			var id, sid, kind, status, jid string
			var from, to *uuid.UUID
			var seq int
			var exp *time.Time
			_ = rows.Scan(&id, &sid, &kind, &status, &jid, &from, &to, &seq, &exp)
			item := M{"kind": kind, "assignmentId": id, "sampleId": sid, "status": status, "journeyId": jid, "sequence": seq, "history": timeline(r.Context(), a.db, "assignment", id)}
			if from != nil {
				item["fromLocationId"] = from
			}
			if to != nil {
				item["toLocationId"] = to
			}
			if exp != nil {
				item["offerExpiresAt"] = exp
			}
			switch status {
			case "offered", "pending":
				pending = append(pending, item)
			case "completed", "declined", "cancelled":
				done = append(done, item)
			default:
				inprog = append(inprog, item)
			}
		}
	}
	ok(w, 200, M{"pending": pending, "inProgress": inprog, "completed": done})
}

func (a *App) journeyData(ctx context.Context, id string, actor Actor) (M, error) {
	var parent *uuid.UUID
	var ver int
	var mode, status string
	var eta *time.Time
	var cost float64
	var used int
	var samples []uuid.UUID
	var stops []byte
	var valid bool
	var replan *string
	if a.db.QueryRow(ctx, "select parent_journey_id,plan_version,route_mode,status,estimated_delivery_at,total_cost_units,capacity_used,sample_ids,ordered_stops,valid,replan_status from labapp.journeys where id=$1", id).Scan(&parent, &ver, &mode, &status, &eta, &cost, &used, &samples, &stops, &valid, &replan) != nil {
		return nil, pgx.ErrNoRows
	}
	var os any
	_ = json.Unmarshal(stops, &os)
	legs := []M{}
	rows, _ := a.db.Query(ctx, "select id,sequence,status,from_location_id,to_location_id,worker_id,sample_id,kind from labapp.assignments where journey_id=$1 order by sequence", id)
	defer rows.Close()
	assigned := []uuid.UUID{}
	for rows.Next() {
		var aid, sid, st, kind string
		var seq int
		var from, to, worker *uuid.UUID
		_ = rows.Scan(&aid, &seq, &st, &from, &to, &worker, &sid, &kind)
		if actor.Role != "administrator" && actor.Role != "dispatcher" && actor.Role != "requester" && worker != nil && *worker != actor.ID {
			continue
		}
		l := M{"assignmentId": aid, "sequence": seq, "status": st, "sampleId": sid}
		if from != nil {
			l["fromLocationId"] = from
		}
		if to != nil {
			l["toLocationId"] = to
		}
		if worker != nil {
			l["workerId"] = worker
			assigned = append(assigned, *worker)
		}
		legs = append(legs, l)
	}
	m := M{"journeyId": id, "planVersion": ver, "routeMode": mode, "status": status, "sampleIds": samples, "orderedStops": os, "legs": legs}
	if actor.Role == "administrator" || actor.Role == "dispatcher" {
		m["totalCostUnits"] = cost
		m["capacityUsed"] = used
		m["capacityAvailable"] = used
		m["assignedWorkerIds"] = assigned
		m["valid"] = valid
	}
	if actor.Role != "requester" && actor.Role != "administrator" && actor.Role != "dispatcher" {
		m["scope"] = "assigned_legs"
		ids := []string{}
		for _, l := range legs {
			ids = append(ids, str(l["assignmentId"]))
		}
		m["assignmentIds"] = ids
	}
	if parent != nil {
		m["parentJourneyId"] = parent
	}
	if eta != nil {
		m["estimatedDeliveryAt"] = eta
	}
	if replan != nil {
		m["replanStatus"] = *replan
	}
	return m, nil
}
func (a *App) readJourney(w http.ResponseWriter, r *http.Request) {
	x, yes := a.require(w, r, "administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !yes {
		return
	}
	var q M
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	m, e := a.journeyData(r.Context(), str(q["journeyId"]), x)
	if e != nil {
		fail(w, 404, "not_found", "journey not found")
		return
	}
	if x.Role == "requester" {
		var count int
		_ = a.db.QueryRow(r.Context(), "select count(*) from labapp.journeys j join labapp.samples s on s.id=any(j.sample_ids) join labapp.requests r on r.id=s.request_id where j.id=$1 and r.requester_id=$2", str(q["journeyId"]), x.ID).Scan(&count)
		if count == 0 {
			fail(w, 403, "forbidden", "not permitted")
			return
		}
	}
	ok(w, 200, m)
}

func capacityMap(c, ru, cc, cr int) M {
	return M{"capacityUnits": c, "reservedUnits": ru, "availableUnits": c - ru, "cooledCapacityUnits": cc, "cooledReservedUnits": cr, "cooledAvailableUnits": cc - cr}
}
func (a *App) operationsData(ctx context.Context) M {
	samples := []M{}
	rows, _ := a.db.Query(ctx, `select s.id,s.status,r.id,r.origin,r.delivery_deadline,s.current_holder_id,s.active_journey_id,s.latest_location,s.location_recorded_at from labapp.samples s join labapp.requests r on r.id=s.request_id`)
	for rows.Next() {
		var id, status, rid string
		var origin, loc []byte
		var dl time.Time
		var holder, jid *uuid.UUID
		var lat *time.Time
		_ = rows.Scan(&id, &status, &rid, &origin, &dl, &holder, &jid, &loc, &lat)
		m := M{"sampleId": id, "status": status, "requestId": rid, "origin": jsonMap(origin), "deliveryDeadline": dl, "locationStale": lat == nil || time.Since(*lat) > 15*time.Minute}
		if holder != nil {
			m["currentHolderId"] = holder
		}
		if jid != nil {
			m["activeJourneyId"] = jid
		}
		if lat != nil {
			m["latestLocation"] = jsonMap(loc)
			m["locationRecordedAt"] = lat
		}
		samples = append(samples, m)
	}
	rows.Close()
	workers := []M{}
	rows, _ = a.db.Query(ctx, `select u.id,coalesce(u.full_name,u.username),u.roles,u.available,u.capacity_units,count(a.id),max(s.location_recorded_at),max(s.latest_location::text) from labapp.users u left join labapp.assignments a on a.worker_id=u.id and a.status not in ('completed','cancelled') left join labapp.samples s on s.id=a.sample_id where u.roles&&array['collection_professional','delivery_partner'] group by u.id`)
	for rows.Next() {
		var id, n string
		var rs []string
		var av bool
		var cap, count int
		var at *time.Time
		var l *string
		_ = rows.Scan(&id, &n, &rs, &av, &cap, &count, &at, &l)
		m := M{"workerId": id, "fullName": n, "roles": rs, "available": av, "status": map[bool]string{true: "available", false: "unavailable"}[av], "capacityUnits": cap, "assignmentCount": count, "locationStale": at == nil || time.Since(*at) > 15*time.Minute}
		if l != nil {
			m["latestLocation"] = jsonMap([]byte(*l))
			m["locationRecordedAt"] = at
		}
		workers = append(workers, m)
	}
	rows.Close()
	locations := []M{}
	rows, _ = a.db.Query(ctx, `select l.id,l.name,l.latitude,l.longitude,l.active,l.coverage_km,l.handling_minutes,l.functions,coalesce(c.capacity_units,0),coalesce(c.reserved_units,0),coalesce(c.cooled_capacity_units,0),coalesce(c.cooled_reserved_units,0),coalesce(array_agg(la.sample_type_id) filter(where la.accepts),'{}') from labapp.locations l left join labapp.capacities c on c.resource_id=l.id left join labapp.lab_acceptance la on la.laboratory_id=l.id group by l.id,c.resource_id`)
	for rows.Next() {
		var id, n string
		var lat, lon, cov float64
		var active bool
		var hm, cap, ru, cc, cr int
		var f []byte
		var accepted []uuid.UUID
		_ = rows.Scan(&id, &n, &lat, &lon, &active, &cov, &hm, &f, &cap, &ru, &cc, &cr, &accepted)
		locations = append(locations, M{"id": id, "locationId": id, "name": n, "coordinate": M{"latitude": lat, "longitude": lon}, "active": active, "coverageKm": cov, "handlingMinutes": hm, "functions": jsonMap(f), "capacity": capacityMap(cap, ru, cc, cr), "acceptedSampleTypeIds": accepted})
	}
