func (a *App) assignment(w http.ResponseWriter, r *http.Request) {
	x, yes := a.require(w, r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !yes {
		return
	}
	var q M
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	id, key := str(q["assignmentId"]), str(q["idempotencyKey"])
	var worker uuid.UUID
	var status, sid string
	if a.db.QueryRow(r.Context(), "select coalesce(offered_to,worker_id),status,sample_id from labapp.assignments where id=$1", id).Scan(&worker, &status, &sid) != nil {
		fail(w, 404, "not_found", "assignment not found")
		return
	}
	if worker != x.ID {
		fail(w, 403, "ineligible_worker", "assignment was offered to another worker")
		return
	}
	if key == "" {
		fail(w, 400, "idempotency_required", "idempotency key required")
		return
	}
	switch r.URL.Path {
	case "/api/accept-assignment":
		if status != "offered" && status != "pending" {
			fail(w, 409, "assignment_inactive", "assignment is not active")
			return
		}
		_, _ = a.db.Exec(r.Context(), "update labapp.assignments set status='accepted',worker_id=$2 where id=$1", id, x.ID)
		a.audit(r.Context(), x, "accept_assignment", "assignment", id, true, M{})
		ok(w, 201, M{"assignmentId": id, "workerId": x.ID, "status": "accepted"})
	case "/api/decline-assignment":
		at := time.Now().UTC()
		if q["declinedAt"] != nil {
			at, _ = parseTime(q["declinedAt"])
		}
		_, _ = a.db.Exec(r.Context(), "update labapp.assignments set status='pending',worker_id=null,offered_to=null where id=$1", id)
		a.audit(r.Context(), x, "decline_assignment", "assignment", id, true, M{"reason": q["reason"]})
		ok(w, 201, M{"assignmentId": id, "status": "pending", "declinedBy": x.ID, "declinedAt": at})
	default:
		newstatus := str(q["status"])
		if status != "accepted" && status != "in_progress" {
			fail(w, 409, "assignment_inactive", "assignment must be accepted")
			return
		}
		dbstatus := newstatus
		if newstatus == "in_progress" || newstatus == "in_transit" || newstatus == "picked_up" {
			dbstatus = "in_progress"
		}
		completed := newstatus == "completed" || newstatus == "delivered"
		_, _ = a.db.Exec(r.Context(), "update labapp.assignments set status=$2,completed_at=case when $3 then now() end where id=$1", id, dbstatus, completed)
		a.audit(r.Context(), x, "update_assignment_progress", "assignment", id, true, M{"status": newstatus})
		ok(w, 201, M{"assignmentId": id, "sampleId": sid, "status": newstatus})
	}
}
