		id = uid()
		f := functionMap(q["functions"])
		_, e := a.db.Exec(r.Context(), `insert into labapp.locations(id,name,latitude,longitude,coverage_km,handling_minutes,active,functions) values($1,$2,$3,$4,$5,$6,$7,$8);insert into labapp.capacities(resource_id) values($1)`, id, str(q["name"]), lat, lon, coverage, handling, q["active"], certification(f))
