			fail(w, 400, "invalid_location_function", "location could not be created")
			return
		}
	} else {
		f := any(nil)
		if _, ok := q["functions"]; ok {
			f = certification(functionMap(q["functions"]))
		}
		tag, _ := a.db.Exec(r.Context(), "update labapp.locations set name=$2,latitude=$3,longitude=$4,coverage_km=coalesce(nullif($5,0),coverage_km),handling_minutes=coalesce($6,handling_minutes),functions=coalesce($7,functions) where id=$1", id, str(q["name"]), lat, lon, coverage, q["handlingMinutes"], f)
		if tag.RowsAffected() == 0 {
			fail(w, 404, "not_found", "location not found")
			return
		}
	}
	a.publishSnapshot(r.Context())
	a.audit(r.Context(), x, "configure_location", "location", id, true, M{})
	a.locationResponse(w, r.Context(), 201, id)
