func (a *App) collect(w http.ResponseWriter, r *http.Request) {
	x, yes := a.require(w, r, "collection_professional")
	if !yes {
		return
	}
	var q M
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	sid, aid := str(q["sampleId"]), str(q["assignmentId"])
	var worker uuid.UUID
	var status, ct string
	var min, max, temp float64
	var earliest, latest time.Time
	if a.db.QueryRow(r.Context(), `select a.worker_id,a.status,s.container_type,s.temperature_min_c,s.temperature_max_c,r.earliest_collection_at,r.latest_collection_at from labapp.assignments a join labapp.samples s on s.id=a.sample_id join labapp.requests r on r.id=s.request_id where a.id=$1 and s.id=$2`, aid, sid).Scan(&worker, &status, &ct, &min, &max, &earliest, &latest) != nil {
		fail(w, 404, "not_found", "assignment not found")
		return
	}
	if worker != x.ID || status != "accepted" {
		fail(w, 409, "collection_not_ready", "collection assignment is not accepted")
		return
	}
	at, e := parseTime(q["collectedAt"])
	if e != nil || at.Before(earliest) || at.After(latest) {
		fail(w, 409, "outside_collection_window", "collection is outside its window")
		return
	}
	temp = num(q["observedTemperatureC"])
	compliant := str(q["containerType"]) == ct && temp >= min && temp <= max
	_, _ = a.db.Exec(r.Context(), "update labapp.samples set status=case when $3 then 'sealed' else 'exception' end,current_holder_id=$2,sealed_at=$4,exception=case when $3 then exception else jsonb_build_object('reason','handling_noncompliant') end where id=$1", sid, x.ID, compliant, at)
	_, _ = a.db.Exec(r.Context(), "update labapp.assignments set status='completed',completed_at=$2 where id=$1", aid, at)
	a.audit(r.Context(), x, "collect_and_seal", "sample", sid, true, M{"compliant": compliant})
	ok(w, 201, M{"sampleId": sid, "status": "sealed", "currentHolderId": x.ID, "sealedAt": at, "handlingCompliant": compliant})
}

func (a *App) handoff(w http.ResponseWriter, r *http.Request) {
	x, yes := a.require(w, r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !yes {
		return
	}
	var q M
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	if r.URL.Path == "/api/initiate-handoff" {
		sid := str(q["sampleId"])
		var holder uuid.UUID
		if a.db.QueryRow(r.Context(), "select current_holder_id from labapp.samples where id=$1", sid).Scan(&holder) != nil {
			fail(w, 404, "not_found", "sample not found")
			return
		}
		if holder != x.ID {
			fail(w, 409, "custody_required", "only current holder may initiate handoff")
			return
		}
		id := uid()
		at, e := parseTime(q["initiatedAt"])
		if e != nil {
			fail(w, 400, "invalid_time", "invalid time")
			return
		}
		_, e = a.db.Exec(r.Context(), `insert into labapp.handoffs(id,sample_id,from_assignment_id,to_assignment_id,sender_id,receiver_id,initiated_at) values($1,$2,$3,$4,$5,$6,$7)`, id, sid, str(q["fromAssignmentId"]), str(q["toAssignmentId"]), x.ID, str(q["receiverId"]), at)
		if e != nil {
			fail(w, 409, "handoff_in_progress", "handoff already exists")
			return
		}
		a.audit(r.Context(), x, "initiate_handoff", "sample", sid, true, M{"handoffId": id})
		ok(w, 201, M{"handoffId": id, "senderId": x.ID, "receiverId": q["receiverId"], "currentHolderId": x.ID, "status": "pending"})
		return
	}
	id := str(q["handoffId"])
	side := str(q["confirmationSide"])
	var sender, receiver, current uuid.UUID
	var sc, rc bool
	var sid string
	if a.db.QueryRow(r.Context(), "select sender_id,receiver_id,sender_confirmed,receiver_confirmed,sample_id from labapp.handoffs where id=$1", id).Scan(&sender, &receiver, &sc, &rc, &sid) != nil {
		fail(w, 404, "not_found", "handoff not found")
		return
	}
	if (side == "sender" && x.ID != sender) || (side == "receiver" && x.ID != receiver) {
		fail(w, 403, "wrong_confirmation_party", "confirmation party mismatch")
		return
	}
	if side == "sender" {
		sc = true
	} else {
		rc = true
	}
	status := "pending"
	current = sender
	if sc && rc {
		status = "confirmed"
		current = receiver
	}
	_, _ = a.db.Exec(r.Context(), "update labapp.handoffs set sender_confirmed=$2,receiver_confirmed=$3,status=$4,completed_at=case when $4='confirmed' then now() end where id=$1", id, sc, rc, status)
	if status == "confirmed" {
		_, _ = a.db.Exec(r.Context(), "update labapp.samples set current_holder_id=$2,status='in_transit' where id=$1", sid, receiver)
	}
	a.audit(r.Context(), x, "confirm_handoff", "sample", sid, true, M{"handoffId": id, "side": side, "status": status})
	ok(w, 201, M{"handoffId": id, "status": status, "senderConfirmed": sc, "receiverConfirmed": rc, "currentHolderId": current})
}
