func (a *App) labOutcome(w http.ResponseWriter, r *http.Request) {
	x, yes := a.require(w, r, "laboratory_team")
	if !yes {
		return
	}
	var q M
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	sid, lab := str(q["sampleId"]), str(q["laboratoryId"])
	var assigned *uuid.UUID
	_ = a.db.QueryRow(r.Context(), "select assigned_location_id from labapp.users where id=$1", x.ID).Scan(&assigned)
	if assigned == nil || assigned.String() != lab {
		fail(w, 403, "forbidden", "operator is assigned to another laboratory")
		return
	}
	if strings.Contains(r.URL.Path, "exception") {
		id := uid()
		reason := str(q["reason"])
		b, _ := json.Marshal(M{"exceptionId": id, "reason": reason, "observedAt": q["observedAt"]})
		_, _ = a.db.Exec(r.Context(), "update labapp.samples set status='exception',exception=$2 where id=$1", sid, b)
