		fail(w, 400, "invalid_time", "invalid receipt time")
		return
	}
	var holder uuid.UUID
	if a.db.QueryRow(r.Context(), "select current_holder_id from labapp.samples where id=$1 and target_laboratory_id=$2", sid, lab).Scan(&holder) != nil {
