	if e != nil {
		fail(w, 401, "unauthorized", "authentication required")
		return
	}
	var rid, requester, otype, stype, ct, status, service string
	var origin []byte
	var req, deadline time.Time
	var min, max float64
	var inc []uuid.UUID
	var jid, lab *uuid.UUID
	var loc []byte
	var locAt *time.Time
	e = a.db.QueryRow(r.Context(), `select r.id,r.requester_id,r.origin,r.origin_type,r.requested_at,r.delivery_deadline,s.sample_type_id,s.container_type,s.temperature_min_c,s.temperature_max_c,s.incompatible_sample_types,s.status,s.serviceability,s.active_journey_id,s.target_laboratory_id,s.latest_location,s.location_recorded_at from labapp.samples s join labapp.requests r on r.id=s.request_id where s.id=$1`, id).Scan(&rid, &requester, &origin, &otype, &req, &deadline, &stype, &ct, &min, &max, &inc, &status, &service, &jid, &lab, &loc, &locAt)
