func (a *App) planChange(w http.ResponseWriter, r *http.Request) {
	x, yes := a.require(w, r, "administrator", "dispatcher")
	if !yes {
		return
	}
	var q M
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	jid := str(q["journeyId"])
	if jid == "" {
		jid = str(q["targetJourneyId"])
	}
	expected := int(num(q["expectedPlanVersion"]))
	var version int
	var status string
	if a.db.QueryRow(r.Context(), "select plan_version,status from labapp.journeys where id=$1", jid).Scan(&version, &status) != nil {
		fail(w, 404, "not_found", "journey not found")
		return
	}
	if expected != version {
		fail(w, 409, "stale_plan", "plan version is stale")
		return
	}
	if status == "completed" || status == "cancelled" {
		fail(w, 409, "completed_work_immutable", "completed work cannot be changed")
		return
	}
	if r.URL.Path == "/api/cancel-journey" {
		_, _ = a.db.Exec(r.Context(), "update labapp.journeys set status='cancelled',plan_version=plan_version+1 where id=$1", jid)
		_, _ = a.db.Exec(r.Context(), "update labapp.assignments set status='cancelled' where journey_id=$1 and status not in ('completed')", jid)
		var ids []uuid.UUID
		_ = a.db.QueryRow(r.Context(), "select sample_ids from labapp.journeys where id=$1", jid).Scan(&ids)
		for _, id := range ids {
			a.releaseCapacity(r.Context(), id.String())
		}
		a.audit(r.Context(), x, "cancel_journey", "journey", jid, true, M{})
		ok(w, 201, M{"journeyId": jid, "status": "cancelled", "sampleIds": ids})
		return
	}
	if r.URL.Path == "/api/split-journey" {
		newid := uid()
		samples := stringArray(q["sampleIds"])
		_, e := a.db.Exec(r.Context(), `insert into labapp.journeys(id,parent_journey_id,plan_version,route_mode,status,estimated_delivery_at,total_cost_units,capacity_used,sample_ids,ordered_stops,valid) select $2,id,1,route_mode,status,estimated_delivery_at,total_cost_units,capacity_used,$3::uuid[],ordered_stops,valid from labapp.journeys where id=$1;update labapp.journeys set sample_ids=array(select unnest(sample_ids) except select unnest($3::uuid[])),plan_version=plan_version+1 where id=$1`, jid, newid, samples)
		if e != nil {
			fail(w, 409, "invalid_split", "split failed")
			return
		}
		one, _ := a.journeyData(r.Context(), jid, x)
		two, _ := a.journeyData(r.Context(), newid, x)
		a.audit(r.Context(), x, "split_journey", "journey", jid, true, M{"splitJourneyId": newid})
		ok(w, 201, M{"journey": one, "splitJourney": two})
		return
	}
	if r.URL.Path == "/api/merge-journeys" {
		sources := stringArray(q["sourceJourneyIds"])
		_, _ = a.db.Exec(r.Context(), "update labapp.journeys set sample_ids=(select array_agg(distinct x) from unnest(sample_ids || $2::uuid[]) x),plan_version=plan_version+1 where id=$1", jid, sources)
		m, _ := a.journeyData(r.Context(), jid, x)
		ok(w, 201, m)
		return
	}
	replan := "replaced"
	_, _ = a.db.Exec(r.Context(), "update labapp.journeys set plan_version=plan_version+1,replan_status=$2 where id=$1", jid, replan)
	a.audit(r.Context(), x, "change_plan", "journey", jid, true, M{"path": r.URL.Path, "changes": q["changes"]})
	m, _ := a.journeyData(r.Context(), jid, x)
	if r.URL.Path == "/api/reroute-journey" {
		ok(w, 201, M{"journeyId": jid, "replanStatus": "replaced", "replacementPlanId": jid, "replacementJourney": m})
	} else {
		ok(w, 201, m)
	}
}
