		two, _ := a.journeyData(r.Context(), newid, x)
		a.audit(r.Context(), x, "split_journey", "journey", jid, true, M{"splitJourneyId": newid})
		ok(w, 201, M{"journey": one, "splitJourney": two})
		return
	}
	if r.URL.Path == "/api/merge-journeys" {
		sources := stringArray(q["sourceJourneyIds"])
