func (a *App) events(w http.ResponseWriter, r *http.Request) {
	if _, yes := a.require(w, r, "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team"); !yes {
		return
	}
	cursor, _ := strconv.ParseInt(r.URL.Query().Get("cursor"), 10, 64)
	rows, _ := a.db.Query(r.Context(), "select id,type,entity_type,entity_id,payload,created_at from labapp.realtime_events where id>$1 order by id limit 100", cursor)
	defer rows.Close()
	out := []M{}
	var last = cursor
	for rows.Next() {
		var id int64
		var t, et, eid string
		var p []byte
		var at time.Time
		_ = rows.Scan(&id, &t, &et, &eid, &p, &at)
		var pm M
		_ = json.Unmarshal(p, &pm)
		out = append(out, M{"id": id, "type": t, "entityType": et, "entityId": eid, "payload": pm, "createdAt": at})
		last = id
	}
	ok(w, 200, M{"events": out, "cursor": last})
}

