func hav(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.
	dlat := (lat2 - lat1) * math.Pi / 180
	dlon := (lon2 - lon1) * math.Pi / 180
	s := math.Sin(dlat/2)*math.Sin(dlat/2) + math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*math.Sin(dlon/2)*math.Sin(dlon/2)
	return 2 * R * math.Asin(math.Sqrt(s))
}

type svc struct {
	Serviceable             bool
	Reason, Lab, OriginNode string
	Arrival                 time.Time
	Version                 int
	Connections, Nodes      []string
	Cooled                  bool
}

func (a *App) service(ctx context.Context, q M) svc {
	out := svc{Reason: "outside_service_coverage", Version: 1}
	_ = a.db.QueryRow(ctx, "select max(version) from labapp.serviceability_snapshots").Scan(&out.Version)
	c, _ := q["origin"].(map[string]any)
	lat, lon := num(c["latitude"]), num(c["longitude"])
	origin := str(q["originNodeId"])
	if origin == "" {
		rows, _ := a.db.Query(ctx, "select id,latitude,longitude,coverage_km from labapp.locations where active and coalesce((functions->>'collection_point')::boolean,false)")
		defer rows.Close()
		best := 99999.
		for rows.Next() {
			var id string
			var la, lo, cv float64
			_ = rows.Scan(&id, &la, &lo, &cv)
			d := hav(lat, lon, la, lo)
			if d <= cv && d < best {
				best = d
				origin = id
			}
		}
	}
	if origin == "" {
		return out
	}
	out.OriginNode = origin
	if err := a.db.QueryRow(ctx, "select requires_cooled_route from labapp.sample_types where id=$1 and active", str(q["sampleTypeId"])).Scan(&out.Cooled); err != nil {
		out.Reason = "handling_rules_unsatisfied"
		return out
	}
	row := a.db.QueryRow(ctx, `with recursive routes(node,connection_ids,node_ids,minutes) as (
		select $1::uuid,array[]::uuid[],array[$1::uuid],0
		union all
		select c.to_location_id,r.connection_ids||c.id,r.node_ids||c.to_location_id,r.minutes+c.travel_minutes+n.handling_minutes
		from routes r join labapp.connections c on c.from_location_id=r.node and c.active
		join labapp.locations n on n.id=c.to_location_id and n.active
		left join labapp.capacities cp on cp.resource_id=c.id
		where cardinality(r.node_ids)<8 and not c.to_location_id=any(r.node_ids) and (not $3 or c.cooled)
		and case when $3 then coalesce(cp.cooled_capacity_units-cp.cooled_reserved_units,0)>0 else coalesce(cp.capacity_units-cp.reserved_units,0)>0 end)
		select l.id,r.connection_ids,r.node_ids,now()+r.minutes*interval '1 minute'
		from routes r join labapp.locations l on l.id=r.node and coalesce((l.functions->>'laboratory')::boolean,false)
		join labapp.lab_acceptance la on la.laboratory_id=l.id and la.sample_type_id=$2 and la.accepts
		left join labapp.capacities lp on lp.resource_id=l.id
		where case when $3 then coalesce(lp.cooled_capacity_units-lp.cooled_reserved_units,0)>0 else coalesce(lp.capacity_units-lp.reserved_units,0)>0 end
		order by r.minutes limit 1`, origin, str(q["sampleTypeId"]), out.Cooled)
	if row.Scan(&out.Lab, &out.Connections, &out.Nodes, &out.Arrival) != nil {
		out.Reason = "no_route"
		return out
	}
	deadline, e := parseTime(q["deliveryDeadline"])
	if e != nil || out.Arrival.After(deadline) {
		out.Reason = "deadline_unreachable"
		return out
	}
	out.Serviceable = true
	out.Reason = "serviceable"
	return out
}
