	at, _ := parseTime(q["occurredAt"])
	_, _ = a.db.Exec(r.Context(), "insert into labapp.disruptions(id,resource_type,resource_id,reason,occurred_at,result) values($1,$2,$3,$4,$5,$6)", id, str(q["resourceType"]), str(q["resourceId"]), str(q["reason"]), at, b)
	a.audit(r.Context(), x, "report_disruption", str(q["resourceType"]), str(q["resourceId"]), true, M{})
