func capacityMap(c, ru, cc, cr int) M {
	return M{"capacityUnits": c, "reservedUnits": ru, "availableUnits": c - ru, "cooledCapacityUnits": cc, "cooledReservedUnits": cr, "cooledAvailableUnits": cc - cr}
}
func (a *App) operationsData(ctx context.Context) M {
	samples := []M{}
	rows, _ := a.db.Query(ctx, `select s.id,s.status,r.id,r.origin,r.delivery_deadline,s.current_holder_id,s.active_journey_id,s.latest_location,s.location_recorded_at from labapp.samples s join labapp.requests r on r.id=s.request_id`)
	for rows.Next() {
		var id, status, rid string
		var origin, loc []byte
		var dl time.Time
		var holder, jid *uuid.UUID
		var lat *time.Time
		_ = rows.Scan(&id, &status, &rid, &origin, &dl, &holder, &jid, &loc, &lat)
		m := M{"sampleId": id, "status": status, "requestId": rid, "origin": jsonMap(origin), "deliveryDeadline": dl, "locationStale": lat == nil || time.Since(*lat) > 15*time.Minute}
		if holder != nil {
			m["currentHolderId"] = holder
		}
		if jid != nil {
			m["activeJourneyId"] = jid
		}
		if lat != nil {
			m["latestLocation"] = jsonMap(loc)
			m["locationRecordedAt"] = lat
		}
		samples = append(samples, m)
	}
	rows.Close()
	workers := []M{}
	rows, _ = a.db.Query(ctx, `select u.id,coalesce(u.full_name,u.username),u.roles,u.available,u.capacity_units,count(a.id),max(s.location_recorded_at),max(s.latest_location::text) from labapp.users u left join labapp.assignments a on a.worker_id=u.id and a.status not in ('completed','cancelled') left join labapp.samples s on s.id=a.sample_id where u.roles&&array['collection_professional','delivery_partner'] group by u.id`)
	for rows.Next() {
		var id, n string
		var rs []string
		var av bool
		var cap, count int
		var at *time.Time
		var l *string
		_ = rows.Scan(&id, &n, &rs, &av, &cap, &count, &at, &l)
		m := M{"workerId": id, "fullName": n, "roles": rs, "available": av, "status": map[bool]string{true: "available", false: "unavailable"}[av], "capacityUnits": cap, "assignmentCount": count, "locationStale": at == nil || time.Since(*at) > 15*time.Minute}
		if l != nil {
			m["latestLocation"] = jsonMap([]byte(*l))
			m["locationRecordedAt"] = at
		}
		workers = append(workers, m)
	}
	rows.Close()
	locations := []M{}
	rows, _ = a.db.Query(ctx, `select l.id,l.name,l.latitude,l.longitude,l.active,l.coverage_km,l.handling_minutes,l.functions,coalesce(c.capacity_units,0),coalesce(c.reserved_units,0),coalesce(c.cooled_capacity_units,0),coalesce(c.cooled_reserved_units,0),coalesce(array_agg(la.sample_type_id) filter(where la.accepts),'{}') from labapp.locations l left join labapp.capacities c on c.resource_id=l.id left join labapp.lab_acceptance la on la.laboratory_id=l.id group by l.id,c.resource_id`)
	for rows.Next() {
		var id, n string
		var lat, lon, cov float64
		var active bool
		var hm, cap, ru, cc, cr int
		var f []byte
		var accepted []uuid.UUID
		_ = rows.Scan(&id, &n, &lat, &lon, &active, &cov, &hm, &f, &cap, &ru, &cc, &cr, &accepted)
		locations = append(locations, M{"id": id, "locationId": id, "name": n, "coordinate": M{"latitude": lat, "longitude": lon}, "active": active, "coverageKm": cov, "handlingMinutes": hm, "functions": jsonMap(f), "capacity": capacityMap(cap, ru, cc, cr), "acceptedSampleTypeIds": accepted})
	}
	rows.Close()
	connections := []M{}
	rows, _ = a.db.Query(ctx, `select x.id,x.from_location_id,x.to_location_id,x.travel_minutes,x.cost_units,x.cooled,x.active,coalesce(c.capacity_units,0),coalesce(c.reserved_units,0),coalesce(c.cooled_capacity_units,0),coalesce(c.cooled_reserved_units,0) from labapp.connections x left join labapp.capacities c on c.resource_id=x.id`)
	for rows.Next() {
		var id, from, to string
		var tm, cap, ru, cc, cr int
		var cost float64
		var cool, active bool
		_ = rows.Scan(&id, &from, &to, &tm, &cost, &cool, &active, &cap, &ru, &cc, &cr)
		connections = append(connections, M{"id": id, "connectionId": id, "fromLocationId": from, "toLocationId": to, "travelMinutes": tm, "costUnits": cost, "cooled": cool, "active": active, "capacity": capacityMap(cap, ru, cc, cr)})
	}
	rows.Close()
	return M{"samples": samples, "workers": workers, "locations": locations, "connections": connections, "routes": []M{}, "handoffs": []M{}, "delays": []M{}, "exceptions": []M{}, "assignmentCountSpread": 0, "ineligibleAssignmentCount": 0}
}
