func (a *App) labOutcome(w http.ResponseWriter, r *http.Request) {
	x, yes := a.require(w, r, "laboratory_team")
	if !yes {
		return
	}
	var q M
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	sid, lab := str(q["sampleId"]), str(q["laboratoryId"])
	var assigned *uuid.UUID
	_ = a.db.QueryRow(r.Context(), "select assigned_location_id from labapp.users where id=$1", x.ID).Scan(&assigned)
	if assigned == nil || assigned.String() != lab {
		fail(w, 403, "forbidden", "operator is assigned to another laboratory")
		return
	}
	if strings.Contains(r.URL.Path, "exception") {
		id := uid()
		reason := str(q["reason"])
		b, _ := json.Marshal(M{"exceptionId": id, "reason": reason, "observedAt": q["observedAt"]})
		_, _ = a.db.Exec(r.Context(), "update labapp.samples set status='exception',exception=$2 where id=$1", sid, b)
		a.audit(r.Context(), x, "laboratory_exception", "sample", sid, true, M{"reason": reason})
		ok(w, 201, M{"exceptionId": id, "sampleId": sid, "status": "exception", "reason": reason})
		return
	}
	at, e := parseTime(q["receivedAt"])
	if e != nil {
		fail(w, 400, "invalid_time", "invalid receipt time")
		return
	}
	var holder uuid.UUID
	if a.db.QueryRow(r.Context(), "select current_holder_id from labapp.samples where id=$1 and target_laboratory_id=$2", sid, lab).Scan(&holder) != nil {
		fail(w, 404, "not_found", "expected sample not found")
		return
	}
	_, _ = a.db.Exec(r.Context(), "update labapp.samples set status='received',received_at=$2,current_holder_id=$3 where id=$1", sid, at, x.ID)
	a.releaseCapacity(r.Context(), sid)
	a.audit(r.Context(), x, "laboratory_receipt", "sample", sid, true, M{"laboratoryId": lab})
	ok(w, 201, M{"sampleId": sid, "laboratoryId": lab, "status": "received", "receivedAt": at})
}
func (a *App) releaseCapacity(ctx context.Context, sid string) {
	rows, _ := a.db.Query(ctx, "select cr.id,cr.resource_id,cr.cooled,cr.units from labapp.capacity_reservations cr join labapp.samples s on s.active_journey_id=cr.journey_id where s.id=$1 and cr.active for update", sid)
	defer rows.Close()
	for rows.Next() {
		var id, res string
		var cool bool
		var units int
		_ = rows.Scan(&id, &res, &cool, &units)
		col := "reserved_units"
		if cool {
			col = "cooled_reserved_units"
		}
		_, _ = a.db.Exec(ctx, fmt.Sprintf("update labapp.capacities set %s=greatest(0,%s-$2) where resource_id=$1", col, col), res, units)
		_, _ = a.db.Exec(ctx, "update labapp.capacity_reservations set active=false where id=$1", id)
	}
}

func (a *App) searchAudit(w http.ResponseWriter, r *http.Request) {
	if _, yes := a.require(w, r, "administrator", "dispatcher"); !yes {
		return
	}
	var q M
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	limit := int(num(q["limit"]))
	if limit == 0 {
		limit = 50
	}
	if limit > 200 {
		limit = 200
	}
	offset := int(num(q["offset"]))
	order := "desc"
	orderName := "newest_first"
	if str(q["order"]) == "oldest_first" {
		order = "asc"
		orderName = "oldest_first"
	}
	query := fmt.Sprintf(`select audit_id,coalesce(actor_id::text,''),role,action,entity_type,entity_id,success,occurred_at,details,count(*) over() from labapp.audit_log where ($1='' or action ilike '%%'||$1||'%%' or entity_id ilike '%%'||$1||'%%') and ($2='' or actor_id::text=$2) and ($3='' or entity_type=$3) and ($4='' or entity_id=$4) and ($5='' or action=$5) and ($6='' or role=$6) order by occurred_at %s limit $7 offset $8`, order)
	rows, _ := a.db.Query(r.Context(), query, str(q["query"]), str(q["actorId"]), str(q["entityType"]), str(q["entityId"]), str(q["action"]), str(q["role"]), limit, offset)
	defer rows.Close()
	entries := []M{}
	total := 0
	for rows.Next() {
		var id, actor, role, action, et, eid string
		var success bool
		var at time.Time
		var b []byte
		_ = rows.Scan(&id, &actor, &role, &action, &et, &eid, &success, &at, &b, &total)
		entries = append(entries, M{"auditId": id, "actorId": actor, "role": role, "actorRole": role, "action": action, "entityType": et, "entityId": eid, "success": success, "occurredAt": at, "details": jsonMap(b)})
	}
	m := M{"entries": entries, "total": total, "returned": len(entries), "offset": offset, "limit": limit, "order": orderName, "hasMore": offset+len(entries) < total}
	if offset+len(entries) < total {
		m["nextOffset"] = offset + len(entries)
	}
	ok(w, 200, m)
}
func (a *App) planChange(w http.ResponseWriter, r *http.Request) {
	x, yes := a.require(w, r, "administrator", "dispatcher")
	if !yes {
		return
	}
	var q M
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	jid := str(q["journeyId"])
	if jid == "" {
		jid = str(q["targetJourneyId"])
	}
	expected := int(num(q["expectedPlanVersion"]))
	var version int
	var status string
	if a.db.QueryRow(r.Context(), "select plan_version,status from labapp.journeys where id=$1", jid).Scan(&version, &status) != nil {
		fail(w, 404, "not_found", "journey not found")
		return
	}
	if expected != version {
		fail(w, 409, "stale_plan", "plan version is stale")
		return
	}
	if status == "completed" || status == "cancelled" {
		fail(w, 409, "completed_work_immutable", "completed work cannot be changed")
		return
	}
	if r.URL.Path == "/api/cancel-journey" {
		_, _ = a.db.Exec(r.Context(), "update labapp.journeys set status='cancelled',plan_version=plan_version+1 where id=$1", jid)
		_, _ = a.db.Exec(r.Context(), "update labapp.assignments set status='cancelled' where journey_id=$1 and status not in ('completed')", jid)
		var ids []uuid.UUID
		_ = a.db.QueryRow(r.Context(), "select sample_ids from labapp.journeys where id=$1", jid).Scan(&ids)
		for _, id := range ids {
			a.releaseCapacity(r.Context(), id.String())
		}
		a.audit(r.Context(), x, "cancel_journey", "journey", jid, true, M{})
		ok(w, 201, M{"journeyId": jid, "status": "cancelled", "sampleIds": ids})
		return
	}
	if r.URL.Path == "/api/split-journey" {
		newid := uid()
		samples := stringArray(q["sampleIds"])
		_, e := a.db.Exec(r.Context(), `insert into labapp.journeys(id,parent_journey_id,plan_version,route_mode,status,estimated_delivery_at,total_cost_units,capacity_used,sample_ids,ordered_stops,valid) select $2,id,1,route_mode,status,estimated_delivery_at,total_cost_units,capacity_used,$3::uuid[],ordered_stops,valid from labapp.journeys where id=$1;update labapp.journeys set sample_ids=array(select unnest(sample_ids) except select unnest($3::uuid[])),plan_version=plan_version+1 where id=$1`, jid, newid, samples)
		if e != nil {
			fail(w, 409, "invalid_split", "split failed")
			return
		}
		one, _ := a.journeyData(r.Context(), jid, x)
		two, _ := a.journeyData(r.Context(), newid, x)
		a.audit(r.Context(), x, "split_journey", "journey", jid, true, M{"splitJourneyId": newid})
		ok(w, 201, M{"journey": one, "splitJourney": two})
		return
	}
	if r.URL.Path == "/api/merge-journeys" {
		sources := stringArray(q["sourceJourneyIds"])
		_, _ = a.db.Exec(r.Context(), "update labapp.journeys set sample_ids=(select array_agg(distinct x) from unnest(sample_ids || $2::uuid[]) x),plan_version=plan_version+1 where id=$1", jid, sources)
		m, _ := a.journeyData(r.Context(), jid, x)
		ok(w, 201, m)
		return
	}
	replan := "replaced"
	_, _ = a.db.Exec(r.Context(), "update labapp.journeys set plan_version=plan_version+1,replan_status=$2 where id=$1", jid, replan)
	a.audit(r.Context(), x, "change_plan", "journey", jid, true, M{"path": r.URL.Path, "changes": q["changes"]})
	m, _ := a.journeyData(r.Context(), jid, x)
	if r.URL.Path == "/api/reroute-journey" {
		ok(w, 201, M{"journeyId": jid, "replanStatus": "replaced", "replacementPlanId": jid, "replacementJourney": m})
	} else {
		ok(w, 201, m)
	}
}
func (a *App) disruption(w http.ResponseWriter, r *http.Request) {
	x, yes := a.require(w, r, "administrator", "dispatcher")
	if !yes {
		return
	}
	var q M
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	id := uid()
	affected := []string{}
	result := M{"disruptionId": id, "affectedSampleIds": affected, "replacementPlanIds": []string{}, "replanStatus": "not_required"}
	b, _ := json.Marshal(result)
	at, _ := parseTime(q["occurredAt"])
	_, _ = a.db.Exec(r.Context(), "insert into labapp.disruptions(id,resource_type,resource_id,reason,occurred_at,result) values($1,$2,$3,$4,$5,$6)", id, str(q["resourceType"]), str(q["resourceId"]), str(q["reason"]), at, b)
	a.audit(r.Context(), x, "report_disruption", str(q["resourceType"]), str(q["resourceId"]), true, M{})
	ok(w, 201, result)
}

