package main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"math"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"golang.org/x/crypto/bcrypt"
)

type App struct {
	db   *pgxpool.Pool
	dist string
}
type Actor struct {
	ID             uuid.UUID
	Username, Role string
	Roles          []string
}
type M = map[string]any

var roles = map[string]bool{"administrator": true, "dispatcher": true, "requester": true, "collection_professional": true, "delivery_partner": true, "node_handler": true, "laboratory_team": true}

func main() {
	ctx := context.Background()
	url := os.Getenv("DATABASE_URL")
	if url == "" {
		log.Fatal("DATABASE_URL is required")
	}
	db, err := pgxpool.New(ctx, url)
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()
	db.Config().ConnConfig.RuntimeParams["search_path"] = "labapp,public"
	if err = db.Ping(ctx); err != nil {
		log.Fatal(err)
	}
	if err = ensureAdmin(ctx, db); err != nil {
		log.Fatal(err)
	}
	a := &App{db: db, dist: "/workspace/dist"}
	mux := http.NewServeMux()
	mux.HandleFunc("/ready", a.ready)
	mux.HandleFunc("/api/", a.api)
	mux.HandleFunc("/", a.frontend)
	s := &http.Server{Addr: "127.0.0.1:8080", Handler: securityHeaders(mux), ReadHeaderTimeout: 10 * time.Second}
	log.Printf("Relay listening on http://127.0.0.1:8080")
	log.Fatal(s.ListenAndServe())
}
func ensureAdmin(ctx context.Context, db *pgxpool.Pool) error {
	var n int
	if err := db.QueryRow(ctx, "select count(*) from labapp.users").Scan(&n); err != nil {
		return fmt.Errorf("database not reset: %w", err)
	}
	if n > 0 {
		return nil
	}
	u, p := os.Getenv("ADMIN_USERNAME"), os.Getenv("ADMIN_PASSWORD")
	if u == "" || p == "" {
		return errors.New("ADMIN_USERNAME and ADMIN_PASSWORD are required for first start")
	}
	h, _ := bcrypt.GenerateFromPassword([]byte(p), bcrypt.DefaultCost)
	_, err := db.Exec(ctx, "insert into labapp.users(username,password_hash,full_name,roles) values($1,$2,$1,array['administrator'])", u, string(h))
	return err
}
func securityHeaders(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("X-Content-Type-Options", "nosniff")
		w.Header().Set("X-Frame-Options", "DENY")
		w.Header().Set("Referrer-Policy", "same-origin")
		next.ServeHTTP(w, r)
	})
}
func (a *App) ready(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" {
		fail(w, 405, "method_not_allowed", "method not allowed")
		return
	}
	if a.db.Ping(r.Context()) != nil {
		write(w, 503, M{"status": "starting"})
		return
	}
	write(w, 200, M{"status": "ready"})
}
func (a *App) frontend(w http.ResponseWriter, r *http.Request) {
	p := filepath.Join(a.dist, filepath.Clean(r.URL.Path))
	if r.URL.Path == "/" {
		p = filepath.Join(a.dist, "index.html")
	}
	if st, e := os.Stat(p); e == nil && !st.IsDir() {
		http.ServeFile(w, r, p)
		return
	}
	http.ServeFile(w, r, filepath.Join(a.dist, "index.html"))
}
func write(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}
func ok(w http.ResponseWriter, status int, v any) { write(w, status, M{"data": v}) }
func fail(w http.ResponseWriter, status int, code, msg string) {
	write(w, status, M{"error": msg, "code": code})
}
func decode(r *http.Request, v any) error {
	d := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
	d.DisallowUnknownFields()
	return d.Decode(v)
}
func uid() string { return uuid.NewString() }
func hashBody(v any) string {
	b, _ := json.Marshal(v)
	h := sha256.Sum256(b)
	return hex.EncodeToString(h[:])
}
func contains(a []string, s string) bool {
	for _, v := range a {
		if v == s {
			return true
		}
	}
	return false
}
func str(v any) string {
	if v == nil {
		return ""
	}
	return fmt.Sprint(v)
}
func arr(v any) []any {
	if x, ok := v.([]any); ok {
		return x
	}
	return []any{}
}
func num(v any) float64 {
	if x, ok := v.(float64); ok {
		return x
	}
	return 0
}
func parseTime(v any) (time.Time, error) { return time.Parse(time.RFC3339, str(v)) }
func roleAllowed(role string, allowed ...string) bool {
	if role == "administrator" {
		return true
	}
	for _, x := range allowed {
		if role == x {
			return true
		}
	}
	return false
}

func (a *App) actor(r *http.Request) (Actor, error) {
	h := strings.TrimSpace(strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer "))
	if h == "" {
		return Actor{}, errors.New("unauthorized")
	}
	var x Actor
	var rr []string
	err := a.db.QueryRow(r.Context(), `select u.id,u.username,u.roles,s.active_role from labapp.sessions s join labapp.users u on u.id=s.user_id where s.token=$1 and s.expires_at>now() and u.active`, h).Scan(&x.ID, &x.Username, &rr, &x.Role)
	x.Roles = rr
	return x, err
}
func (a *App) require(w http.ResponseWriter, r *http.Request, allowed ...string) (Actor, bool) {
	x, e := a.actor(r)
	if e != nil {
		fail(w, 401, "unauthorized", "authentication required")
		return x, false
	}
	if x.Role == "" {
		fail(w, 409, "role_not_selected", "select an active role")
		return x, false
	}
	if !roleAllowed(x.Role, allowed...) {
		a.audit(r.Context(), x, "permission_check", "operation", r.URL.Path, false, M{})
		fail(w, 403, "forbidden", "active role is not permitted")
		return x, false
	}
	return x, true
}
func (a *App) audit(ctx context.Context, x Actor, action, typ, id string, success bool, details M) {
	b, _ := json.Marshal(details)
	_, _ = a.db.Exec(ctx, `with logged as (insert into labapp.audit_log(actor_id,role,action,entity_type,entity_id,success,details) values($1,$2,$3,$4,$5,$6,$7) returning audit_id) insert into labapp.realtime_events(type,entity_type,entity_id,payload) select $3,$4,$5,$7 from logged`, x.ID, x.Role, action, typ, id, success, b)
}
func (a *App) idem(ctx context.Context, x Actor, op, key string, req any) (int, json.RawMessage, bool, error) {
	if key == "" {
		return 0, nil, false, errors.New("required")
	}
	var st int
	var raw []byte
	var old string
	err := a.db.QueryRow(ctx, "select status,response,request_hash from labapp.idempotency where actor_id=$1 and operation=$2 and key=$3", x.ID, op, key).Scan(&st, &raw, &old)
	if err == nil {
		if old != hashBody(req) {
			return 409, nil, true, errors.New("conflict")
		}
		return st, raw, true, nil
	}
	if !errors.Is(err, pgx.ErrNoRows) {
		return 0, nil, false, err
	}
	return 0, nil, false, nil
}
func (a *App) saveIdem(ctx context.Context, x Actor, op, key string, req any, status int, response M) {
	if key == "" {
		return
	}
	b, _ := json.Marshal(response)
	_, _ = a.db.Exec(ctx, "insert into labapp.idempotency(actor_id,operation,key,request_hash,status,response) values($1,$2,$3,$4,$5,$6) on conflict do nothing", x.ID, op, key, hashBody(req), status, b)
}

func (a *App) api(w http.ResponseWriter, r *http.Request) {
	p := r.URL.Path
	if p == "/api/authenticate-user" {
		a.login(w, r)
		return
	}
	if r.Method == "GET" && strings.HasPrefix(p, "/api/read-sample-state/") {
		a.readSample(w, r, strings.TrimPrefix(p, "/api/read-sample-state/"))
		return
	}
	if r.Method == "GET" && strings.HasPrefix(p, "/api/read-user/") {
		a.readUser(w, r, strings.TrimPrefix(p, "/api/read-user/"))
		return
	}
	switch p {
	case "/api/ui/bootstrap":
		a.bootstrap(w, r)
	case "/api/events":
		a.events(w, r)
	case "/api/select-active-role":
		a.selectRole(w, r)
	case "/api/create-user":
		a.createUser(w, r)
	case "/api/update-user-access":
		a.updateUser(w, r)
	case "/api/create-sample-type", "/api/update-sample-type":
		a.sampleType(w, r)
	case "/api/create-location", "/api/update-location":
		a.location(w, r)
	case "/api/create-connection":
		a.connection(w, r)
	case "/api/set-location-status", "/api/set-location-function-status", "/api/set-connection-status":
		a.setStatus(w, r)
	case "/api/configure-capacity":
		a.capacity(w, r)
	case "/api/configure-laboratory-acceptance":
		a.labAcceptance(w, r)
	case "/api/set-worker-availability":
		a.workerAvailability(w, r)
	case "/api/check-serviceability":
		a.checkService(w, r)
	case "/api/read-serviceability-snapshot":
		a.snapshot(w, r)
	case "/api/create-collection-request", "/api/ingest-presealed-sample":
		a.createRequest(w, r)
	case "/api/list-role-work":
		a.roleWork(w, r)
	case "/api/read-sample-lifecycle":
		a.lifecycle(w, r)
	case "/api/read-journey-plan":
		a.readJourney(w, r)
	case "/api/read-operations-state":
		a.operations(w, r)
	case "/api/accept-assignment", "/api/decline-assignment", "/api/update-assignment-progress":
		a.assignment(w, r)
	case "/api/record-worker-location":
		a.workerLocation(w, r)
	case "/api/collect-and-seal-sample":
		a.collect(w, r)
	case "/api/initiate-handoff", "/api/confirm-handoff":
		a.handoff(w, r)
	case "/api/record-handling-checkpoint":
		a.checkpoint(w, r)
	case "/api/confirm-laboratory-receipt", "/api/record-laboratory-exception":
		a.labOutcome(w, r)
	case "/api/search-audit-trail":
		a.searchAudit(w, r)
	case "/api/edit-active-plan", "/api/reroute-journey", "/api/cancel-journey", "/api/split-journey", "/api/merge-journeys":
		a.planChange(w, r)
	case "/api/report-disruption":
		a.disruption(w, r)
	default:
		fail(w, 404, "not_found", "operation not found")
	}
}

func (a *App) login(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		fail(w, 405, "method_not_allowed", "method not allowed")
		return
	}
	var q struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	var id uuid.UUID
	var h string
	var rs []string
	var active bool
	if a.db.QueryRow(r.Context(), "select id,password_hash,roles,active from labapp.users where username=$1", q.Username).Scan(&id, &h, &rs, &active) != nil || !active || bcrypt.CompareHashAndPassword([]byte(h), []byte(q.Password)) != nil {
		fail(w, 401, "invalid_credentials", "invalid username or password")
		return
	}
	token := uuid.NewString() + uuid.NewString()
	role := ""
	if len(rs) == 1 {
		role = rs[0]
	}
	_, _ = a.db.Exec(r.Context(), "insert into labapp.sessions(token,user_id,active_role,expires_at) values($1,$2,$3,now()+interval '24 hours')", token, id, role)
	x := Actor{ID: id, Username: q.Username, Role: role, Roles: rs}
	a.audit(r.Context(), x, "sign_in", "user", id.String(), true, M{})
	ok(w, 200, M{"sessionToken": token, "userId": id, "roles": rs, "activeRole": role})
}
func (a *App) selectRole(w http.ResponseWriter, r *http.Request) {
	x, e := a.actor(r)
	if e != nil {
		fail(w, 401, "unauthorized", "authentication required")
		return
	}
	var q struct {
		Role string `json:"role"`
	}
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	if !contains(x.Roles, q.Role) {
		fail(w, 403, "role_not_assigned", "role is not assigned")
		return
	}
	tok := strings.TrimSpace(strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer "))
