func (a *App) releaseCapacity(ctx context.Context, sid string) {
	rows, _ := a.db.Query(ctx, "select cr.id,cr.resource_id,cr.cooled,cr.units from labapp.capacity_reservations cr join labapp.samples s on s.active_journey_id=cr.journey_id where s.id=$1 and cr.active for update", sid)
	defer rows.Close()
	for rows.Next() {
		var id, res string
		var cool bool
		var units int
		_ = rows.Scan(&id, &res, &cool, &units)
		col := "reserved_units"
		if cool {
			col = "cooled_reserved_units"
		}
		_, _ = a.db.Exec(ctx, fmt.Sprintf("update labapp.capacities set %s=greatest(0,%s-$2) where resource_id=$1", col, col), res, units)
		_, _ = a.db.Exec(ctx, "update labapp.capacity_reservations set active=false where id=$1", id)
	}
}

func (a *App) searchAudit(w http.ResponseWriter, r *http.Request) {
	if _, yes := a.require(w, r, "administrator", "dispatcher"); !yes {
		return
	}
	var q M
	if decode(r, &q) != nil {
		fail(w, 400, "invalid_json", "invalid request")
		return
	}
	limit := int(num(q["limit"]))
	if limit == 0 {
		limit = 50
	}
	if limit > 200 {
		limit = 200
	}
	offset := int(num(q["offset"]))
	order := "desc"
	orderName := "newest_first"
	if str(q["order"]) == "oldest_first" {
		order = "asc"
		orderName = "oldest_first"
	}
	query := fmt.Sprintf(`select audit_id,coalesce(actor_id::text,''),role,action,entity_type,entity_id,success,occurred_at,details,count(*) over() from labapp.audit_log where ($1='' or action ilike '%%'||$1||'%%' or entity_id ilike '%%'||$1||'%%') and ($2='' or actor_id::text=$2) and ($3='' or entity_type=$3) and ($4='' or entity_id=$4) and ($5='' or action=$5) and ($6='' or role=$6) order by occurred_at %s limit $7 offset $8`, order)
	rows, _ := a.db.Query(r.Context(), query, str(q["query"]), str(q["actorId"]), str(q["entityType"]), str(q["entityId"]), str(q["action"]), str(q["role"]), limit, offset)
	defer rows.Close()
	entries := []M{}
	total := 0
	for rows.Next() {
		var id, actor, role, action, et, eid string
		var success bool
		var at time.Time
		var b []byte
		_ = rows.Scan(&id, &actor, &role, &action, &et, &eid, &success, &at, &b, &total)
		entries = append(entries, M{"auditId": id, "actorId": actor, "role": role, "actorRole": role, "action": action, "entityType": et, "entityId": eid, "success": success, "occurredAt": at, "details": jsonMap(b)})
	}
	m := M{"entries": entries, "total": total, "returned": len(entries), "offset": offset, "limit": limit, "order": orderName, "hasMore": offset+len(entries) < total}
	if offset+len(entries) < total {
		m["nextOffset"] = offset + len(entries)
	}
	ok(w, 200, m)
}
